fn parse_size(s: &str) -> Option<(char, u64)> {
    // Format <+-><NUM><UNIT>, UNIT case-insensitive, allowed: b,k,m,g,t,ki,mi,gi,ti with optional trailing b
    if s.is_empty() { return None; }
    let (op, rest) = if s.starts_with('+') || s.starts_with('-') {
        (s.chars().next().unwrap(), &s[1..])
    } else {
        ('=', s)
    };
    if rest.is_empty() { return None; }
    // Split numeric prefix and unit suffix
    let mut num_end = 0;
    for (i, c) in rest.char_indices() {
        if c.is_ascii_digit() { num_end = i + c.len_utf8(); } else { break; }
    }
    if num_end == 0 { return None; }
    let num_str = &rest[..num_end];
    let unit_str = &rest[num_end..];
    if unit_str.is_empty() { return None; } // must have unit
    // Check for spaces? No spaces allowed (as we saw "10 " fails, " 10k" fails)
    if num_str.contains(' ') || unit_str.contains(' ') { return None; }
    let num: u64 = num_str.parse().ok()?;
    let unit_lower = unit_str.to_lowercase();
    // Allowed units: b, k, kb, ki, kib, m, mb, mi, mib, g, gb, gi, gib, t, tb, ti, tib
    let mult: u64 = match unit_lower.as_str() {
        "b" => 1,
        "k" | "kb" => 1000,
        "m" | "mb" => 1000*1000,
        "g" | "gb" => 1000*1000*1000,
        "t" | "tb" => 1000*1000*1000*1000,
        "ki" | "kib" => 1024,
        "mi" | "mib" => 1024*1024,
        "gi" | "gib" => 1024*1024*1024,
        "ti" | "tib" => 1024*1024*1024*1024,
        _ => return None,
    };
    let val = num.checked_mul(mult)?;
    Some((op, val))
}

