        "%Y-%m-%d %H:%M",
        "%Y-%m-%d",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%dT%H:%M",
        "%H:%M:%S",
        "%H:%M",
    ];
    for fmt in &fmts {
        if let Ok(ndt) = NaiveDateTime::parse_from_str(s, fmt) {
            // Convert as local time
            let local = chrono::Local.from_local_datetime(&ndt).single();
            if let Some(dt) = local {
                let secs = dt.timestamp();
                if secs >= 0 {
                    return Some(std::time::UNIX_EPOCH + std::time::Duration::from_secs(secs as u64));
                }
            }
            // Fallback: treat as UTC?
            let utc = chrono::Utc.from_utc_datetime(&ndt);
            let secs = utc.timestamp();
            if secs >= 0 {
                return Some(std::time::UNIX_EPOCH + std::time::Duration::from_secs(secs as u64));
            }
            return None;
        }
        // Try NaiveDate
        if *fmt == "%Y-%m-%d" {
            if let Ok(d) = NaiveDate::parse_from_str(s, fmt) {
                let ndt = d.and_hms_opt(0,0,0).unwrap();
                let local = chrono::Local.from_local_datetime(&ndt).single();
                if let Some(dt) = local {
