    // Parse by scanning: number (digits) + optional spaces + unit (letters) + optional spaces, repeated.
    let mut total_secs: u64 = 0;
    let mut i = 0;
    let bytes = s.as_bytes();
    let n = bytes.len();
    let mut found_any = false;
    while i < n {
        // Skip spaces between sequences? Actually spaces allowed between number and unit, and between sequences.
        // But leading/trailing already checked. So skip spaces?
