        // Parse number
        let start_num = i;
        while i < n && bytes[i].is_ascii_digit() { i += 1; }
        if start_num == i { return None; } // expected number
        let num_str = &s[start_num..i];
        let num: u64 = num_str.parse().ok()?;
        // Skip spaces between number and unit
        while i < n && bytes[i] == b' ' { i += 1; }
        if i >= n { return None; } // expected unit
        let start_unit = i;
        while i < n && bytes[i].is_ascii_alphabetic() { i += 1; }
        if start_unit == i { return None; }
        let unit = &s[start_unit..i];
        // Unit must be lower (as we saw uppercase fails)
        if unit.chars().any(|c| c.is_uppercase()) { return None; }
        let secs_per_unit: u64 = match unit {
            "s" | "sec" | "secs" | "second" | "seconds" => 1,
            "m" | "min" | "mins" | "minute" | "minutes" => 60,
            "h" | "hour" | "hours" => 3600,
            "d" | "day" | "days" => 86400,
