// Helpers for display, placeholders, file types, etc.

#[derive(Debug)]
struct EntryInfo {
    path: PathBuf,
    abs_path: PathBuf,
    depth: usize,
    file_type: std::fs::FileType,
    metadata: Option<std::fs::Metadata>,
    is_symlink: bool,
}

fn get_global_fd_ignore() -> Option<PathBuf> {
    // $XDG_CONFIG_HOME/fd/ignore or $HOME/.config/fd/ignore
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        let p = PathBuf::from(xdg).join("fd/ignore");
        if p.is_file() { return Some(p); }
    }
    if let Ok(home) = std::env::var("HOME") {
        let p = PathBuf::from(home).join(".config/fd/ignore");
        if p.is_file() { return Some(p); }
    }
    None
}

fn is_empty_entry(ent: &EntryInfo) -> bool {
    if ent.file_type.is_dir() {
        // Check if dir is empty (no entries, ignoring . and ..)
        match std::fs::read_dir(&ent.path) {
            Ok(mut rd) => rd.next().is_none(),
            Err(_) => false,
        }
    } else if ent.file_type.is_file() {
        match &ent.metadata {
            Some(m) => m.len() == 0,
            None => false,
        }
    } else {
        false
    }
}

fn is_executable_entry(ent: &EntryInfo) -> bool {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        use std::os::unix::fs::PermissionsExt;
        // Only files? Check file type is file?
        // For executable, check any exec bit? Use metadata mode.
        if let Some(m) = &ent.metadata {
            let mode = m.mode();
            return mode & 0o111 != 0;
        }
        // Fallback: check symlink_metadata?
        if let Ok(md) = std::fs::symlink_metadata(&ent.path) {
            let mode = md.permissions().mode();
            return mode & 0o111 != 0;
        }
        false
    }
    #[cfg(not(unix))]
    { false }
}

fn get_mode(ent: &EntryInfo) -> Option<u32> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if let Some(m) = &ent.metadata {
            return Some(m.mode());
        }
        if let Ok(md) = std::fs::symlink_metadata(&ent.path) {
            use std::os::unix::fs::PermissionsExt;
            return Some(md.permissions().mode());
        }
        None
    }
    #[cfg(not(unix))]
    { None }
}

