fn basename_of(path_str: &str) -> String {
    // Get basename (after last / or sep? Use / since we use / internally)
    // For path like "./a/file1.txt" or "a/file1.txt" or "/tmp/a/file1.txt", basename is "file1.txt"
    // For dirs with trailing slash, strip slash first?
    let mut s = path_str;
    // Remove trailing slash(es)
    while s.ends_with('/') && s.len() > 1 {
        s = &s[..s.len()-1];
    }
    // Find last '/'
    if let Some(idx) = s.rfind('/') {
        s[idx+1..].to_string()
    } else {
        s.to_string()
    }
}

fn parent_of(path_str: &str) -> String {
    // Get parent directory (// placeholder)
    // For "a/file1.txt" -> "a", for "file1.txt" -> ".", for "./a/file1.txt" -> "./a", for "/tmp/a/file1.txt" -> "/tmp/a"
