        }
    } else {
        ".".to_string()
    }
}

fn strip_extension(path_str: &str) -> String {
    // Remove last extension (after last '.' in basename, if any)
    // For "a/test.min.js" -> "a/test.min", for "file.txt" -> "file", for "a/file" (no ext) -> "a/file"
    // For hidden files like ".hidden"? Probably no strip? But hidden skipped anyway.
    // Find basename start
    let slash_idx = path_str.rfind('/').map(|i| i+1).unwrap_or(0);
