    // For {//}: parent of file_str (with sep, with ./ prefix? As we saw earlier: {}="./a/test.min.js", {//}="./a" (with ./). Good - parent retains ./ prefix.
    // For {.}: file_str without extension (with ./, sep)
    // For {/.}: basename without extension

    let mut res = String::new();
    let mut i = 0;
    let bytes = arg.as_bytes();
    while i < bytes.len() {
        if i+1 < bytes.len() && bytes[i] == b'{' && bytes[i+1] == b'{' {
            res.push('{');
            i += 2;
            continue;
        }
        if i+1 < bytes.len() && bytes[i] == b'}' && bytes[i+1] == b'}' {
            res.push('}');
            i += 2;
            continue;
        }
        if arg[i..].starts_with("{//}") {
            // parent
            let parent = parent_of(&file_str);
            res.push_str(&parent);
            i += 5;
            continue;
        }
        if arg[i..].starts_with("{/.}") {
            let b = basename_no_ext(&file_str);
            res.push_str(&b);
            i += 5;
            continue;
        }
        if arg[i..].starts_with("{/}") {
            let b = basename_of(&file_str);
            res.push_str(&b);
            i += 4;
            continue;
        }
        if arg[i..].starts_with("{.}") {
            let s = strip_extension(&file_str);
            res.push_str(&s);
            i += 4;
            continue;
        }
        if arg[i..].starts_with("{}") {
            res.push_str(&file_str);
            i += 2;
            continue;
        }
        res.push(bytes[i] as char);
        i += 1;
    }
    res
}

