}

fn get_hostname() -> String {
    // Get hostname via gethostname syscall or /etc/hostname or env?
    let mut buf = [0u8; 256];
    unsafe {
        if libc::gethostname(buf.as_mut_ptr() as *mut i8, buf.len()) == 0 {
            let len = buf.iter().position(|&c| c == 0).unwrap_or(buf.len());
            return String::from_utf8_lossy(&buf[..len]).to_string();
        }
    }
    // Fallback: try env HOSTNAME or read /etc/hostname?
    if let Ok(h) = std::env::var("HOSTNAME") { return h; }
    if let Ok(h) = std::fs::read_to_string("/etc/hostname") { return h.trim().to_string(); }
    "localhost".to_string()
}

// Display path helpers
fn display_path(ent: &EntryInfo, absolute: bool, sep: Option<&str>, strip_dot: bool) -> String {
    // strip_dot: true means strip ./ (no prefix), false means keep ./?
    // Actually our earlier param was confusing. Let's define: if absolute, ignore strip, return absolute with sep.
    // Else: relative path with sep, with or without ./ prefix, plus trailing slash for dirs.
    let mut s: String = if absolute {
        ent.abs_path.to_string_lossy().to_string()
    } else {
        let mut rel = ent.path.to_string_lossy().to_string();
        // Normalize: ent.path may be like "./a/file1.txt" or "a/file1.txt" or "./a" etc.
        // For display without dot (strip), remove leading "./"
        // For display with dot (keep), ensure leading "./" (add if missing, unless absolute or already ./)
        if strip_dot {
            if rel.starts_with("./") {
                rel = rel[2..].to_string();
            }
        } else {
            // keep dot: ensure ./ prefix if not absolute and not already ./ and not empty?
            if !rel.starts_with("./") && !rel.starts_with('/') {
                // Also need to handle paths like "a/file1.txt" -> "./a/file1.txt"? But what about paths from search root "a" with pattern? Original exec gives "./a/..." with dot. Normal without exec gives "a/..." without dot. So for normal (strip), no dot. For exec (keep), dot.
                // So if keep_dot (strip_dot==false), add "./" prefix.
                rel = format!("./{}", rel);
            }
        }
        rel
    };
    // Apply path separator
    if let Some(sep_str) = sep {
        if sep_str != "/" {
            s = s.replace("/", sep_str);
        }
    }
    // Add trailing slash for dirs (if not already)
    // Need to check if ent is dir (including followed symlink dirs?)
    let is_dir = ent.file_type.is_dir() || (ent.is_symlink && std::fs::metadata(&ent.path).map(|m| m.is_dir()).unwrap_or(false));
    if is_dir {
        let sep_char = sep.unwrap_or("/");
        if !s.ends_with(sep_char) {
            s.push_str(sep_char);
        }
    }
    s
}

fn display_path_for_exec(ent: &EntryInfo, absolute: bool, sep: Option<&str>, strip_dot_prefix: bool) -> String {
    // strip_dot_prefix: true means strip ./ (no prefix), false means keep ./ 
    // For exec, auto => keep ./, so strip=false
    // Our display_path takes strip_dot (true=strip, false=keep). So pass strip_dot_prefix directly.
    display_path(ent, absolute, sep, strip_dot_prefix)
}

