fn basename_of(path_str: &str) -> String {
    // Get basename (after last / or sep? Use / since we use / internally)
    // For path like "./a/file1.txt" or "a/file1.txt" or "/tmp/a/file1.txt", basename is "file1.txt"
    // For dirs with trailing slash, strip slash first?
    let mut s = path_str;
    // Remove trailing slash(es)
    while s.ends_with('/') && s.len() > 1 {
        s = &s[..s.len()-1];
    }
    // Find last '/'
    if let Some(idx) = s.rfind('/') {
        s[idx+1..].to_string()
    } else {
        s.to_string()
    }
}

fn parent_of(path_str: &str) -> String {
    // Get parent directory (// placeholder)
    // For "a/file1.txt" -> "a", for "file1.txt" -> ".", for "./a/file1.txt" -> "./a", for "/tmp/a/file1.txt" -> "/tmp/a"
    // For dirs with trailing slash, strip first?
    let mut s = path_str;
    // Remove trailing slash for dirs? For display, dirs have slash, but for parent, we need parent of dir itself? Eg for "a/" (dir a), parent is "."? Or for "a/b/" parent is "a"? Let's see: for entry "a/b/" (dir), {//} should be "a"? Probably.
    // So strip trailing slash, then find parent.
    let mut tmp = s.to_string();
    while tmp.ends_with('/') && tmp.len() > 1 {
        tmp.pop();
    }
    if let Some(idx) = tmp.rfind('/') {
        let parent = &tmp[..idx];
        if parent.is_empty() {
            "/".to_string()
        } else {
            parent.to_string()
        }
    } else {
        ".".to_string()
    }
}

fn strip_extension(path_str: &str) -> String {
    // Remove last extension (after last '.' in basename, if any)
    // For "a/test.min.js" -> "a/test.min", for "file.txt" -> "file", for "a/file" (no ext) -> "a/file"
    // For hidden files like ".hidden"? Probably no strip? But hidden skipped anyway.
    // Find basename start
    let slash_idx = path_str.rfind('/').map(|i| i+1).unwrap_or(0);
    let basename = &path_str[slash_idx..];
    if let Some(dot_idx) = basename.rfind('.') {
        if dot_idx == 0 {
            // Hidden file like ".hidden" with no other dot? Then no extension? Keep as is.
            path_str.to_string()
        } else {
            let cut = slash_idx + dot_idx;
            path_str[..cut].to_string()
        }
    } else {
        path_str.to_string()
    }
}

fn basename_no_ext(path_str: &str) -> String {
    let base = basename_of(path_str);
    if let Some(dot_idx) = base.rfind('.') {
        if dot_idx == 0 {
            base
        } else {
            base[..dot_idx].to_string()
        }
    } else {
        base
    }
}

